class Probe extends RefCounted:
	func invoke(args: Dictionary) -> Dictionary:
		return {"echo": args.get("value", "")}

func _run():
	var api = Engine.get_singleton("AutopilotTools")
	if api == null:
		return {"error": "AutopilotTools singleton not registered"}
	var probe := Probe.new()
	var definition := {
		"name": "user_echo_probe",
		"description": "Echo probe registered by the L2 user_tools_code_mode test",
		"category": "User",
		"tags": ["user", "test", "echo"],
		"side_effect": "",
		"params": [
			{
				"name": "value",
				"type": "string",
				"description": "Value to echo back",
				"required": true
			}
		]
	}
	var handle = api.register_tool(definition, Callable(probe, "invoke"))
	return {"handle": handle, "has": api.has_tool("user_echo_probe")}

